import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { RATING_SCALE, notchChange, notchCalculator } from '../../src/ratings/notch.mjs';

const EXPECTED_SCALE = [
  'AAA', 'AA+', 'AA', 'AA-', 'A+', 'A', 'A-',
  'BBB+', 'BBB', 'BBB-', 'BB+', 'BB', 'BB-',
  'B+', 'B', 'B-', 'CCC+', 'CCC', 'CCC-',
];

const INVALID_VALUES = [
  '', '   ', 'D', 'NR', 'CC', 'C', 'AAA-', 'AAA+', 'CCC--', 'BBB++',
  'Baa1', 'BBB +', 'B B B', null, undefined, 3, {},
];

test('AC-1: RATING_SCALE holds the 19 ratings, best first, and is frozen', () => {
  assert.deepStrictEqual(RATING_SCALE, EXPECTED_SCALE);
  assert.equal(RATING_SCALE.length, 19);
  assert.equal(RATING_SCALE[0], 'AAA');
  assert.equal(RATING_SCALE[18], 'CCC-');
  assert.equal(Object.isFrozen(RATING_SCALE), true);
});

test('AC-1: mutating RATING_SCALE throws TypeError and leaves it unchanged', () => {
  assert.throws(() => RATING_SCALE.push('D'), TypeError);
  assert.throws(() => { RATING_SCALE[0] = 'X'; }, TypeError);
  assert.deepStrictEqual(RATING_SCALE, EXPECTED_SCALE);
});

test('AC-2: notchChange returns index(current) - index(previous)', () => {
  const cases = [
    ['BBB+', 'BB+', 3], ['BBB+', 'BBB-', 2], ['BBB+', 'BBB', 1],
    ['AAA', 'AA+', 1], ['CCC', 'CCC-', 1], ['BB+', 'BBB+', -3],
    ['A-', 'A', -1], ['AAA', 'CCC-', 18], ['CCC-', 'AAA', -18], ['A', 'A', 0],
  ];
  for (const [p, c, expected] of cases) {
    const result = notchChange(p, c);
    assert.equal(result, expected, `${p} -> ${c}`);
    assert.ok(Number.isInteger(result));
  }
});

test('AC-3: notchChange ignores case and leading/trailing whitespace', () => {
  assert.equal(notchChange('bbb+', 'bb+'), 3);
  assert.equal(notchChange('  BBB+ ', '\tbB+\n'), 3);
  assert.equal(notchChange('aaa', 'AAA'), 0);
  assert.equal(notchChange(' a- ', ' A '), -1);
  assert.equal(notchChange('ccc-', 'aaa'), -18);
});

test('AC-4: notchChange throws RangeError for every invalid value in either position', () => {
  for (const v of INVALID_VALUES) {
    assert.throws(() => notchChange(v, 'A'), RangeError, `first: ${String(v)}`);
    assert.throws(() => notchChange('A', v), RangeError, `second: ${String(v)}`);
  }
});

test('AC-4: notchChange throws RangeError for NR, undefined and missing arguments', () => {
  assert.throws(() => notchChange('NR', 'A'), RangeError);
  assert.throws(() => notchChange('A', 'NR'), RangeError);
  assert.throws(() => notchChange('A', undefined), RangeError);
  assert.throws(() => notchChange(), RangeError);
});

test('AC-4: error message contains the raw invalid string as passed', () => {
  for (const [raw, re] of [['NR', /NR/], ['Baa1', /Baa1/], ['BBB +', /BBB \+/]]) {
    assert.throws(() => notchChange(raw, 'A'), (err) => err instanceof RangeError && re.test(err.message));
    assert.throws(() => notchChange('A', raw), (err) => err instanceof RangeError && re.test(err.message));
  }
  assert.throws(() => notchChange('', 'A'), RangeError);
  assert.throws(() => notchChange('   ', 'A'), RangeError);
});

test('AC-4: non-string input gives RangeError without a second error (symbols, arrays, objects)', () => {
  for (const v of [[], Symbol('x'), 10n, () => 1, Object.create(null)]) {
    assert.throws(() => notchChange(v, 'A'), RangeError);
    assert.throws(() => notchChange('A', v), RangeError);
  }
});

test('AC-5: notchCalculator maps downgrades of 2+ notches to WL 1 or 2', () => {
  assert.deepStrictEqual(notchCalculator('BBB+', 'BB+'), { notches: 3, direction: 'downgrade', wl: 2 });
  assert.deepStrictEqual(notchCalculator('BBB+', 'BBB-'), { notches: 2, direction: 'downgrade', wl: 1 });
  assert.deepStrictEqual(notchCalculator('A', 'BBB+'), { notches: 3, direction: 'downgrade', wl: 2 });
  assert.deepStrictEqual(notchCalculator('AAA', 'CCC-'), { notches: 18, direction: 'downgrade', wl: 2 });
  assert.equal(Object.getPrototypeOf(notchCalculator('BBB+', 'BB+')), Object.prototype);
});

test('AC-6: a 1-notch downgrade is WL 0', () => {
  assert.deepStrictEqual(notchCalculator('BBB+', 'BBB'), { notches: 1, direction: 'downgrade', wl: 0 });
  assert.deepStrictEqual(notchCalculator('CCC', 'CCC-'), { notches: 1, direction: 'downgrade', wl: 0 });
});

test('AC-7: upgrades and unchanged ratings are WL 0', () => {
  assert.deepStrictEqual(notchCalculator('BB+', 'BBB+'), { notches: -3, direction: 'upgrade', wl: 0 });
  assert.deepStrictEqual(notchCalculator('A-', 'A'), { notches: -1, direction: 'upgrade', wl: 0 });
  assert.deepStrictEqual(notchCalculator('CCC-', 'AAA'), { notches: -18, direction: 'upgrade', wl: 0 });
  assert.deepStrictEqual(notchCalculator('A', 'A'), { notches: 0, direction: 'unchanged', wl: 0 });
