// Rating scale and notch calculation (REQ-06-02, Indicator 13 thresholds per C2).
// Pure functions: no I/O, no side effects.

export const RATING_SCALE = Object.freeze([
  'AAA', 'AA+', 'AA', 'AA-', 'A+', 'A', 'A-',
  'BBB+', 'BBB', 'BBB-', 'BB+', 'BB', 'BB-',
  'B+', 'B', 'B-', 'CCC+', 'CCC', 'CCC-',
]);

function describeValue(value) {
  if (typeof value === 'string') return `"${value}"`;
  try {
    return String(value);
  } catch {
    return Object.prototype.toString.call(value);
  }
}

// Returns the index of the rating in RATING_SCALE; throws RangeError if invalid.
function ratingIndex(value) {
  if (typeof value !== 'string') {
    throw new RangeError(`Invalid rating: ${describeValue(value)} (expected a string)`);
  }
  const index = RATING_SCALE.indexOf(value.trim().toUpperCase());
  if (index === -1) {
    throw new RangeError(`Invalid rating: ${describeValue(value)}`);
  }
  return index;
}

// Signed notch change; positive = downgrade, negative = upgrade.
export function notchChange(previous, current) {
  const previousIndex = ratingIndex(previous);
  const currentIndex = ratingIndex(current);
  return currentIndex - previousIndex;
}

export function notchCalculator(previous, current) {
  const notches = notchChange(previous, current);
  const direction = notches > 0 ? 'downgrade' : notches < 0 ? 'upgrade' : 'unchanged';
  const wl = notches >= 3 ? 2 : notches === 2 ? 1 : 0;
  return { notches, direction, wl };
}

