const PACKAGE_URL = new URL('../../package.json', import.meta.url);

test('AC-10: downgrades map to WL 1 (one notch) or 2 (two or more notches)', () => {
  const cases = [
    ['A', 'A-', 1],
    ['CCC', 'CCC-', 1],
    ['A', 'BBB+', 2],
    ['A', 'BBB', 2],
    ['BBB+', 'BB+', 2],
    ['AAA', 'CCC-', 2],
    ['AAA', 'AA+', 1],
    ['BBB+', 'BBB-', 2],
  ];
  for (const [previous, current, expected] of cases) {
    const wl = countryRatingChangeWl(previous, current);
    assert.equal(wl, expected, `${previous} -> ${current}`);
    assert.ok([0, 1, 2].includes(wl));
  }
});

test('AC-11: upgrades and unchanged ratings give WL 0', () => {
  const cases = [
    ['A-', 'A'],
    ['BB+', 'BBB+'],
    ['CCC-', 'AAA'],
    ['A', 'A'],
    ['bbb', ' BBB '],
  ];
  for (const [previous, current] of cases) {
    assert.equal(countryRatingChangeWl(previous, current), 0, `${previous} -> ${current}`);
  }
});

test('AC-12: differs deliberately from notchCalculator().wl (C6)', () => {
  const cases = [
    ['BBB+', 'BBB', 1, 0],
    ['BBB+', 'BBB-', 2, 1],
