    ['BB+', 'BBB+', 0, 0],
  ];
  for (const [previous, current, indicator12, calculator] of cases) {
    assert.equal(countryRatingChangeWl(previous, current), indicator12, `ind12 ${previous} -> ${current}`);
    assert.equal(notchCalculator(previous, current).wl, calculator, `calc ${previous} -> ${current}`);
  }
});

test('AC-13: matches the notchChange rule for all 361 ordered pairs of the scale', () => {
  let count = 0;
  for (const previous of RATING_SCALE) {
    for (const current of RATING_SCALE) {
      const n = notchChange(previous, current);
      const expected = n >= 2 ? 2 : n === 1 ? 1 : 0;
      assert.equal(countryRatingChangeWl(previous, current), expected, `${previous} -> ${current}`);
      count += 1;
    }
  }
  assert.equal(count, 361);
});

test('AC-13: source imports notchChange and holds no copy of the scale', () => {
