    /import\s*\{[^}]*\bnotchChange\b[^}]*\}\s*from\s*['"]\.\.\/ratings\/notch\.mjs['"]/,
  );
  assert.ok(!source.includes('AAA'), 'source must not contain the top rating string');
  assert.ok(!source.includes('CCC-'), 'source must not contain the bottom rating string');
});

test('AC-14: trims and ignores case like notchChange', () => {
