  assert.throws(() => countryRatingChangeWl(null, 'A'), RangeError);
  assert.throws(() => countryRatingChangeWl('', ''), RangeError);
  assert.throws(() => countryRatingChangeWl(), RangeError);
});

test('AC-14: every invalid value throws RangeError in either position', () => {
  const invalid = [
    '', '   ', 'D', 'NR', 'CC', 'C', 'AAA-', 'AAA+', 'CCC--', 'BBB++', 'Baa1',
    'BBB +', 'B B B', null, undefined, 3, {},
  ];
  for (const v of invalid) {
    assert.throws(() => countryRatingChangeWl(v, 'A'), RangeError, `(${String(v)}, 'A')`);
    assert.throws(() => countryRatingChangeWl('A', v), RangeError, `('A', ${String(v)})`);
  }
});

test('AC-15: has exactly two parameters and is deterministic', () => {
  assert.equal(countryRatingChangeWl.length, 2);
  assert.equal(countryRatingChangeWl('A', 'BBB+'), 2);
  assert.equal(countryRatingChangeWl('A', 'BBB+'), 2);
});

test('AC-15: source is pure (no console, process, node: imports, require) and no npm dependencies', () => {
  const source = readFileSync(SOURCE_URL, 'utf8');
