function describeValue(value) {
  if (typeof value === 'string') return `"${value}"`;
  try {
    return String(value);
  } catch {
    return Object.prototype.toString.call(value);
  }
}

// Returns the index of the rating in RATING_SCALE; throws RangeError if invalid.
