  assert.equal(countryRatingChangeWl('BBB+', 'BBB-'), 2);
  assert.equal(countryRatingChangeWl('AAA', 'CCC-'), 2); // 18 notches still 2
});

test('AC-11: upgrades and unchanged ratings give WL 0', () => {
  const cases = [
    ['A-', 'A'],
    ['BB+', 'BBB+'],
    ['CCC-', 'AAA'],
    ['A', 'A'],
    ['bbb', ' BBB '],
  ];
  for (const [p, c] of cases) {
    assert.equal(countryRatingChangeWl(p, c), 0, `${p} -> ${c}`);
  }
});

test('AC-12: indicator differs from notchCalculator().wl only on 1- and 2-notch downgrades (C6)', () => {
  const cases = [
    ['BBB+', 'BBB', 1, 0],
    ['BBB+', 'BBB-', 2, 1],
    ['BBB+', 'BB+', 2, 2],
    ['BB+', 'BBB+', 0, 0],
  ];
  for (const [p, c, ind, calc] of cases) {
    assert.equal(countryRatingChangeWl(p, c), ind, `indicator ${p} -> ${c}`);
    assert.equal(notchCalculator(p, c).wl, calc, `calculator ${p} -> ${c}`);
  }
});

test('AC-13: all 361 ordered pairs of RATING_SCALE follow the notchChange rule', () => {
  assert.equal(RATING_SCALE.length, 19);
  let count = 0;
  for (const p of RATING_SCALE) {
    for (const c of RATING_SCALE) {
      const n = notchChange(p, c);
      const want = n >= 2 ? 2 : n === 1 ? 1 : 0;
      assert.equal(countryRatingChangeWl(p, c), want, `${p} -> ${c}`);
      assert.equal(want, expectedWl(p, c));
      count++;
    }
  }
  assert.equal(count, 361);
});

test('AC-13: source imports notchChange from ../ratings/notch.mjs and holds no copy of the scale', () => {
  const text = readFileSync(fileURLToPath(srcUrl), 'utf8');
  assert.match(text, /import\s*\{[^}]*\bnotchChange\b[^}]*\}\s*from\s*['"]\.\.\/ratings\/notch\.mjs['"]/);
  assert.ok(!text.includes('AAA'), 'must not contain AAA');
  assert.ok(!text.includes('CCC-'), 'must not contain CCC-');
});

test("AC-14: AC-3-style input is accepted: (' a ','a-') -> 1", () => {
  assert.equal(countryRatingChangeWl(' a ', 'a-'), 1);
});

test('AC-14: invalid input throws RangeError (named examples and no arguments)', () => {
  assert.throws(() => countryRatingChangeWl('A', 'D'), RangeError);
  assert.throws(() => countryRatingChangeWl(null, 'A'), RangeError);
  assert.throws(() => countryRatingChangeWl('', ''), RangeError);
  assert.throws(() => countryRatingChangeWl(), RangeError);
});

test('AC-14: every invalid AC-4 value throws RangeError in either position', () => {
  for (const v of INVALID) {
    assert.throws(() => countryRatingChangeWl(v, 'A'), RangeError, `(${String(v)}, 'A')`);
    assert.throws(() => countryRatingChangeWl('A', v), RangeError, `('A', ${String(v)})`);
  }
});

test('AC-14: RangeError propagates unchanged from notchChange (same error class and message)', () => {
  for (const v of ['D', 'B B B', 'Baa1']) {
    let fromNotch;
    let fromIndicator;
    try { notchChange(v, 'A'); } catch (e) { fromNotch = e; }
    try { countryRatingChangeWl(v, 'A'); } catch (e) { fromIndicator = e; }
    assert.ok(fromNotch instanceof RangeError);
    assert.ok(fromIndicator instanceof RangeError);
    assert.equal(fromIndicator.message, fromNotch.message);
  }
});

test('AC-15: arity is 2 and the result is deterministic', () => {
  assert.equal(countryRatingChangeWl.length, 2);
  assert.equal(countryRatingChangeWl('A', 'BBB+'), 2);
  assert.equal(countryRatingChangeWl('A', 'BBB+'), 2);
});

test('AC-15: source has no console/process/node: imports/require; package.json has no dependencies', () => {
  const text = readFileSync(fileURLToPath(srcUrl), 'utf8');
  const re = /console\.|process\.|from 'node:|require\(/;
  text.split('\n').forEach((line, i) => {
    assert.ok(!re.test(line), `line ${i + 1} matches forbidden pattern: ${line}`);
  });
  const pkg = JSON.parse(readFileSync(fileURLToPath(pkgUrl), 'utf8'));
  assert.ok(!('dependencies' in pkg));
  assert.ok(!('devDependencies' in pkg));
});

test('AC-15: no output is written to stdout/stderr when called', () => {
  const origOut = process.stdout.write;
  const origErr = process.stderr.write;
  let written = 0;
  process.stdout.write = (...a) => { written++; return true; };
  process.stderr.write = (...a) => { written++; return true; };
  try {
    countryRatingChangeWl('A', 'BBB+');
    try { countryRatingChangeWl('x', 'A'); } catch { /* expected */ }
  } finally {
    process.stdout.write = origOut;
    process.stderr.write = origErr;
  }
  assert.equal(written, 0);
});
